 ****************************************************************************/

/* APB clock frequency (80 MHz) */

#define LEDC_CLK_APB_FREQ         (80000000)

/* LEDC timer max reload */

#define LEDC_RELOAD_MAX           (16384)
#define LEDC_RELOAD_MAX_BIT_LEN   (14)

/****************************************************************************
 * Public Functions
 ****************************************************************************/

#ifdef CONFIG_PWM

/****************************************************************************
 * Name: esp32s3_pwm_setup
 *
 * Description:
 *   Initialize LEDC PWM and register the PWM device.
 *
 ****************************************************************************/

int esp32s3_pwm_setup(void)
{
  int ret;
  struct pwm_lowerhalf_s *pwm;

#ifdef CONFIG_ESP32S3_LEDC_TIM0
  pwm = esp32s3_ledc_init(0);
  if (!pwm)
    {
      syslog(LOG_ERR, "ERROR: Failed to get the LEDC PWM 0 lower half\n");
      return -ENODEV;
    }

  ret = pwm_register("/dev/pwm0", pwm);
  if (ret < 0)
    {
      syslog(LOG_ERR, "ERROR: pwm_register failed: %d\n", ret);
      return ret;
    }
#endif

  UNUSED(ret);
  UNUSED(pwm);

  return OK;
}

/****************************************************************************
 * Name: esp32s3_pwm_early_init
 *
 * Description:
 *   Directly configure LEDC hardware to output PWM at boot, before any
 *   app runs. Uses APB clock (80 MHz), timer 0, channel 0.
 *
 *   frequency: 1000 Hz (1 kHz)
 *   duty: 50%
 *   GPIO: CONFIG_ESP32S3_LEDC_CHANNEL0_PIN
 *
 ****************************************************************************/

void esp32s3_pwm_early_init(void)
{
  irqstate_t flags;
  uint32_t regval;
  uint32_t reload;
  uint32_t shift;
  float prescaler;
  uint32_t integral_prescaler;
  uint32_t fractional_prescaler;
  uint32_t duty_reg;
  uint64_t pwmclk = LEDC_CLK_APB_FREQ;
  uint32_t frequency = 1000;
  uint32_t gpio_pin = CONFIG_ESP32S3_LEDC_CHANNEL0_PIN;

  /* Enable LEDC peripheral clock */

  flags = enter_critical_section();

  setbits(SYSTEM_LEDC_CLK_EN, SYSTEM_PERIP_CLK_EN0_REG);
  resetbits(SYSTEM_LEDC_RST, SYSTEM_PERIP_RST_EN0_REG);

  putreg32(1, LEDC_CONF_REG);  /* Select APB clock source */
  setbits(LEDC_CLK_EN, LEDC_CONF_REG);

  leave_critical_section(flags);

  /* Configure GPIO pin for LEDC output */

  esp32s3_configgpio(gpio_pin, OUTPUT | PULLUP);
  esp32s3_gpio_matrix_out(gpio_pin, LEDC_LS_SIG_OUT0_IDX, 0, 0);

  /* Calculate timer prescaler and reload for desired frequency.
   *
   * tpmclk = pwmclk / prescaler
   * frequency = tpmclk / reload
   * => reload = pwmclk / prescaler / frequency
   *
   * Search for the maximum reload value (up to 16384).
   */

  for (reload = LEDC_RELOAD_MAX, shift = LEDC_RELOAD_MAX_BIT_LEN;
       reload > 1;
       reload = (reload >> 1), shift -= 1)
    {
      if (reload * frequency <= pwmclk)
        {
          break;
        }
    }

  prescaler = (float)pwmclk / frequency / reload;
  integral_prescaler = (uint32_t)prescaler;
  fractional_prescaler = (uint32_t)((prescaler - integral_prescaler) * 256);

  if (integral_prescaler == 0)
    {
      integral_prescaler = 1;
    }

  /* Configure timer 0:
   * - Reset timer
   * - Set duty resolution (shift) and clock divider
   * - Update parameters
   */

  flags = enter_critical_section();

  putreg32(LEDC_TIMER0_RST, LEDC_TIMER0_CONF_REG);

  regval = (shift << LEDC_TIMER0_DUTY_RES_S) |
           (fractional_prescaler << LEDC_CLK_DIV_TIMER0_S) |
           (integral_prescaler << (LEDC_CLK_DIV_TIMER0_S + 8));
  putreg32(regval, LEDC_TIMER0_CONF_REG);

  putreg32(regval | LEDC_TIMER0_PARA_UP, LEDC_TIMER0_CONF_REG);

  leave_critical_section(flags);

  /* Calculate duty for 50% output.
   * duty_reg = reload / 2, then shifted left by 4 (hardware format).
   */

  duty_reg = (reload / 2) << 4;

  /* Configure channel 0:
   * - Select timer 0
   * - Set hpoint = 0
   * - Set duty
   * - Enable signal output
   * - Start duty counter
   * - Update parameters
   */

  flags = enter_critical_section();

  putreg32(0, LEDC_CH0_CONF0_REG);
  putreg32(0, LEDC_CH0_CONF1_REG);
  putreg32(0, LEDC_CH0_CONF0_REG);          /* Timer select = 0 */
  putreg32(0, LEDC_CH0_HPOINT_REG);
  putreg32(duty_reg, LEDC_CH0_DUTY_REG);
  setbits(LEDC_SIG_OUT_EN_CH0, LEDC_CH0_CONF0_REG);
  setbits(LEDC_DUTY_START_CH0, LEDC_CH0_CONF1_REG);
  setbits(LEDC_PARA_UP_CH0, LEDC_CH0_CONF0_REG);

  leave_critical_section(flags);

  syslog(LOG_INFO, "PWM early init: %d Hz, 50%% duty on GPIO %d\n",
         frequency, gpio_pin);
}

#endif /* CONFIG_PWM */

