/****************************************************************************
 * Name: esp32s3_ledc_early_start
 *
 * Description:
 *   Directly configure LEDC hardware to output PWM without going through
 *   the upper-half driver. Useful for boot-time PWM output (e.g. camera
 *   XCLK) that must be active before the PWM device is opened.
 *
 * Input Parameters:
 *   timer     - LEDC timer number (0-3)
 *   channel   - LEDC channel number (0-3)
 *   frequency - Desired PWM frequency in Hz
 *   duty      - Duty cycle as b16 value (0x0000=0%, 0x8000=50%, 0xffff=~100%)
 *   pin       - GPIO pin number for PWM output
 *
 * Returned Value:
 *   Zero (OK) on success; a negated errno value on failure.
 *
 ****************************************************************************/

int esp32s3_ledc_early_start(int timer, int channel, uint32_t frequency,
                             uint16_t duty, int pin)
{
  irqstate_t flags;
  uint32_t regval;
  uint32_t reload;
  uint32_t shift;
  float prescaler;
  uint32_t integral_prescaler;
  uint32_t fractional_prescaler;
  uint32_t duty_reg;
  uint64_t pwmclk = LEDC_CLK_APB_FREQ;
  uint32_t timer_conf_reg = LEDC_TIMER0_CONF_REG +
                            timer * (LEDC_TIMER1_CONF_REG -
                                     LEDC_TIMER0_CONF_REG);
  uint32_t ch_conf0_reg = LEDC_CH0_CONF0_REG +
                          channel * (LEDC_CH1_CONF0_REG -
                                     LEDC_CH0_CONF0_REG);
  uint32_t ch_conf1_reg = LEDC_CH0_CONF1_REG +
                          channel * (LEDC_CH1_CONF1_REG -
                                     LEDC_CH0_CONF1_REG);
  uint32_t ch_hpoint_reg = LEDC_CH0_HPOINT_REG +
                           channel * (LEDC_CH1_HPOINT_REG -
                                      LEDC_CH0_HPOINT_REG);
  uint32_t ch_duty_reg = LEDC_CH0_DUTY_REG +
                         channel * (LEDC_CH1_DUTY_REG -
                                    LEDC_CH0_DUTY_REG);

  if (timer < 0 || timer > 3 || channel < 0 || channel > 7 || frequency == 0)
    {
      return -EINVAL;
    }

  /* Enable LEDC peripheral clock */

  flags = enter_critical_section();

  setbits(SYSTEM_LEDC_CLK_EN, SYSTEM_PERIP_CLK_EN0_REG);
  resetbits(SYSTEM_LEDC_RST, SYSTEM_PERIP_RST_EN0_REG);

  putreg32(LEDC_CLK_RES_APB, LEDC_CONF_REG);
  setbits(LEDC_CLK_EN, LEDC_CONF_REG);

  leave_critical_section(flags);

  /* Configure GPIO pin for LEDC output */

  esp32s3_configgpio(pin, OUTPUT | PULLUP);
  esp32s3_gpio_matrix_out(pin, LEDC_LS_SIG_OUT0_IDX + channel, 0, 0);

  /* Calculate timer prescaler and reload.
   *
   * tpmclk = pwmclk / prescaler
   * frequency = tpmclk / reload
   * => reload = pwmclk / prescaler / frequency
   *
   * Search for the maximum reload value (up to 16384).
   */

  for (reload = LEDC_RELOAD_MAX, shift = LEDC_RELOAD_MAX_BIT_LEN;
       reload > 1;
       reload = (reload >> 1), shift -= 1)
    {
      if (reload * frequency <= pwmclk)
        {
          break;
        }
    }

  prescaler = (float)pwmclk / frequency / reload;
  integral_prescaler = (uint32_t)prescaler;
  fractional_prescaler = (uint32_t)((prescaler - integral_prescaler) * 256);

  if (integral_prescaler == 0)
    {
      integral_prescaler = 1;
    }

  /* Configure timer:
   * - Reset timer
   * - Set duty resolution (shift) and clock divider
   * - Update parameters
   */

  flags = enter_critical_section();

  putreg32(LEDC_TIMER0_RST, timer_conf_reg);

  regval = (shift << LEDC_TIMER0_DUTY_RES_S) |
           (fractional_prescaler << LEDC_CLK_DIV_TIMER0_S) |
           (integral_prescaler << (LEDC_CLK_DIV_TIMER0_S + 8));
  putreg32(regval, timer_conf_reg);

  putreg32(regval | LEDC_TIMER0_PARA_UP, timer_conf_reg);

  leave_critical_section(flags);

  /* Calculate duty register value.
   * duty_reg = b16toi(duty * reload + b16HALF), then shift left by 4.
   */

  duty_reg = b16toi(duty * reload + b16HALF) << 4;

  /* Configure channel:
   * - Select timer
   * - Set hpoint = 0
   * - Set duty
   * - Enable signal output
   * - Start duty counter
   * - Update parameters
   */

  flags = enter_critical_section();

  putreg32(0, ch_conf0_reg);
  putreg32(0, ch_conf1_reg);
  putreg32(timer, ch_conf0_reg);
  putreg32(0, ch_hpoint_reg);
  putreg32(duty_reg, ch_duty_reg);
  setbits(LEDC_SIG_OUT_EN_CH0, ch_conf0_reg);
  setbits(LEDC_DUTY_START_CH0, ch_conf1_reg);
  setbits(LEDC_PARA_UP_CH0, ch_conf0_reg);

  leave_critical_section(flags);

  pwminfo("LEDC early start: timer%d ch%d %dHz duty=0x%04x pin%d\n",
          timer, channel, frequency, duty, pin);

  return OK;
}

