/****************************************************************************
 * Name: esp32s3_pwm_early_init
 *
 * Description:
 *   Start PWM output at boot using LEDC timer 0, channel 0 on GPIO
 *   CONFIG_ESP32S3_LEDC_CHANNEL0_PIN. This runs before camera init
 *   to provide the XCLK signal.
 *
 ****************************************************************************/

void esp32s3_pwm_early_init(void)
{
  int ret;

  /* 20 MHz, 50% duty, timer 0, channel 0 */

  ret = esp32s3_ledc_early_start(0, 0, 20000000, 0x8000,
                                 CONFIG_ESP32S3_LEDC_CHANNEL0_PIN);
  if (ret < 0)
    {
      syslog(LOG_ERR, "ERROR: esp32s3_ledc_early_start failed: %d\n", ret);
    }
  else
    {
      syslog(LOG_INFO, "PWM early start: 20MHz on GPIO %d\n",
             CONFIG_ESP32S3_LEDC_CHANNEL0_PIN);
    }
}

#endif /* CONFIG_PWM */

